META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–4: ಎಲ್ಲ ಜ್ಞಾನಗಳಲ್ಲಿ ಶ್ರೇಷ್ಠ ಜ್ಞಾನ, ಭಗವಂತ ಎಲ್ಲ ಜೀವಿಗಳ ತಂದೆ; 5–9: ಸತ್ತ್ವ, ರಜಸ್, ತಮಸ್ ಎಂಬ ಮೂರು ಗುಣಗಳು ಮತ್ತು ಪ್ರತಿಯೊಂದೂ ಹೇಗೆ ಬಂಧಿಸುತ್ತದೆ; 10–13: ಗುಣಗಳು ಒಂದನ್ನೊಂದು ಹೇಗೆ ಅದುಮುತ್ತವೆ, ಪ್ರತಿಯೊಂದರ ಗುರುತುಗಳು; 14–18: ಮರಣ ಸಮಯದಲ್ಲಿ ಪ್ರತಿ ಗುಣ ಎಲ್ಲಿಗೆ ಒಯ್ಯುತ್ತದೆ; 19–20: ಗುಣಗಳನ್ನು ದಾಟುವುದು; 21–27: ಗುಣಾತೀತನ ಲಕ್ಷಣಗಳು ಮತ್ತು ಅಲ್ಲಿಗೆ ಹೇಗೆ ತಲುಪುವುದು.',
)
T = {
1: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಎಲ್ಲ ಜ್ಞಾನಗಳಲ್ಲಿ ಉತ್ತಮವಾದ ಆ ಪರಮ ಜ್ಞಾನವನ್ನು ಮತ್ತೆ ಹೇಳುತ್ತೇನೆ. ಇದನ್ನು ತಿಳಿದು ಎಲ್ಲ ಮುನಿಗಳೂ ಈ ಲೋಕದಿಂದ ಪರಮ ಸಿದ್ಧಿಯನ್ನು ಪಡೆದರು.',
2: 'ಈ ಜ್ಞಾನವನ್ನು ಆಶ್ರಯಿಸಿ ನನ್ನ ಸ್ವಭಾವವನ್ನು ಪಡೆದವರು ಸೃಷ್ಟಿಯ ಸಮಯದಲ್ಲಿ ಹುಟ್ಟುವುದಿಲ್ಲ, ಪ್ರಳಯದ ಸಮಯದಲ್ಲಿ ಕಳವಳಪಡುವುದಿಲ್ಲ.',
3: 'ಹೇ ಭಾರತ, ಮಹತ್ ಬ್ರಹ್ಮ (ಮೂಲ ಪ್ರಕೃತಿ) ನನ್ನ ಗರ್ಭ; ಅದರಲ್ಲಿ ನಾನು ಬೀಜವನ್ನು ಇಡುತ್ತೇನೆ. ಅದರಿಂದಲೇ ಎಲ್ಲ ಜೀವಿಗಳೂ ಹುಟ್ಟುತ್ತವೆ.',
4: 'ಹೇ ಕೌಂತೇಯ, ಎಲ್ಲ ಗರ್ಭಗಳಲ್ಲಿ ಹುಟ್ಟುವ ರೂಪಗಳೆಲ್ಲಕ್ಕೂ ಮಹತ್ ಬ್ರಹ್ಮ ಗರ್ಭ, ಬೀಜ ಕೊಡುವ ತಂದೆ ನಾನು.',
6: 'ಹೇ ಪಾಪರಹಿತ, ಇವುಗಳಲ್ಲಿ ಸತ್ತ್ವ ನಿರ್ಮಲವಾದ್ದರಿಂದ ಪ್ರಕಾಶಮಾನ ಮತ್ತು ದೋಷರಹಿತ. ಅದು ಸುಖದ ಆಸಕ್ತಿಯಿಂದ ಮತ್ತು ಜ್ಞಾನದ ಆಸಕ್ತಿಯಿಂದ ಬಂಧಿಸುತ್ತದೆ.',
7: 'ಹೇ ಕೌಂತೇಯ, ರಜಸ್ಸು ರಾಗಸ್ವಭಾವದ್ದು, ತೃಷ್ಣೆ ಮತ್ತು ಆಸಕ್ತಿಯಿಂದ ಹುಟ್ಟುತ್ತದೆ ಎಂದು ತಿಳಿ. ಅದು ದೇಹಧಾರಿಯನ್ನು ಕರ್ಮದ ಆಸಕ್ತಿಯಿಂದ ಬಂಧಿಸುತ್ತದೆ.',
8: 'ಹೇ ಭಾರತ, ತಮಸ್ಸು ಅಜ್ಞಾನದಿಂದ ಹುಟ್ಟಿದ್ದು, ಎಲ್ಲ ದೇಹಧಾರಿಗಳನ್ನೂ ಮೋಹಗೊಳಿಸುವುದು ಎಂದು ತಿಳಿ. ಅದು ಅಜಾಗರೂಕತೆ, ಆಲಸ್ಯ ಮತ್ತು ನಿದ್ರೆಯಿಂದ ಬಂಧಿಸುತ್ತದೆ.',
9: 'ಹೇ ಭಾರತ, ಸತ್ತ್ವ ಸುಖಕ್ಕೆ, ರಜಸ್ಸು ಕರ್ಮಕ್ಕೆ ಅಂಟಿಸುತ್ತದೆ. ಆದರೆ ತಮಸ್ಸು ಜ್ಞಾನವನ್ನು ಮುಚ್ಚಿ ಅಜಾಗರೂಕತೆಗೆ ಅಂಟಿಸುತ್ತದೆ.',
10: 'ಹೇ ಭಾರತ, ರಜಸ್ಸು ಮತ್ತು ತಮಸ್ಸನ್ನು ಅದುಮಿ ಸತ್ತ್ವ ಹೆಚ್ಚುತ್ತದೆ; ಸತ್ತ್ವ ಮತ್ತು ತಮಸ್ಸನ್ನು ಅದುಮಿ ರಜಸ್ಸು; ಸತ್ತ್ವ ಮತ್ತು ರಜಸ್ಸನ್ನು ಅದುಮಿ ತಮಸ್ಸು ಹೆಚ್ಚುತ್ತದೆ.',
11: 'ಈ ದೇಹದ ಎಲ್ಲ ದ್ವಾರಗಳಲ್ಲೂ ಜ್ಞಾನವೆಂಬ ಬೆಳಕು ಹೊಳೆದಾಗ, ಸತ್ತ್ವ ಹೆಚ್ಚಿದೆ ಎಂದು ತಿಳಿಯಬೇಕು.',
12: 'ಹೇ ಭರತಶ್ರೇಷ್ಠ, ರಜಸ್ಸು ಹೆಚ್ಚಿದಾಗ ಲೋಭ, ಚಟುವಟಿಕೆ, ಕರ್ಮಗಳ ಆರಂಭ, ಅಶಾಂತಿ ಮತ್ತು ಬಯಕೆ ಹುಟ್ಟುತ್ತವೆ.',
13: 'ಹೇ ಕುರುನಂದನ, ತಮಸ್ಸು ಹೆಚ್ಚಿದಾಗ ಕತ್ತಲೆ, ನಿಷ್ಕ್ರಿಯತೆ, ಅಜಾಗರೂಕತೆ ಮತ್ತು ಮೋಹ ಹುಟ್ಟುತ್ತವೆ.',
14: 'ಸತ್ತ್ವ ಹೆಚ್ಚಿರುವಾಗ ದೇಹಧಾರಿ ಮರಣ ಹೊಂದಿದರೆ, ಉತ್ತಮ ಜ್ಞಾನಿಗಳ ನಿರ್ಮಲ ಲೋಕಗಳನ್ನು ಸೇರುತ್ತಾನೆ.',
15: 'ರಜಸ್ಸಿನಲ್ಲಿ ಮರಣ ಹೊಂದಿದರೆ ಕರ್ಮಾಸಕ್ತರಲ್ಲಿ ಹುಟ್ಟುತ್ತಾನೆ. ತಮಸ್ಸಿನಲ್ಲಿ ಮರಣ ಹೊಂದಿದರೆ ಮೂಢ ಯೋನಿಗಳಲ್ಲಿ ಹುಟ್ಟುತ್ತಾನೆ.',
16: 'ಒಳ್ಳೆಯ ಕರ್ಮದ ಫಲವನ್ನು ಸಾತ್ತ್ವಿಕ ಮತ್ತು ನಿರ್ಮಲ ಎನ್ನುತ್ತಾರೆ. ರಜಸ್ಸಿನ ಫಲ ದುಃಖ, ತಮಸ್ಸಿನ ಫಲ ಅಜ್ಞಾನ.',
17: 'ಸತ್ತ್ವದಿಂದ ಜ್ಞಾನ, ರಜಸ್ಸಿನಿಂದ ಲೋಭ ಹುಟ್ಟುತ್ತವೆ. ತಮಸ್ಸಿನಿಂದ ಅಜಾಗರೂಕತೆ, ಮೋಹ ಮತ್ತು ಅಜ್ಞಾನ ಹುಟ್ಟುತ್ತವೆ.',
18: 'ಸತ್ತ್ವದಲ್ಲಿರುವವರು ಮೇಲಕ್ಕೆ ಹೋಗುತ್ತಾರೆ, ರಜಸ್ಸಿನಲ್ಲಿರುವವರು ಮಧ್ಯದಲ್ಲಿರುತ್ತಾರೆ. ಅಧಮ ಗುಣವಾದ ತಮಸ್ಸಿನ ಪ್ರವೃತ್ತಿಯಲ್ಲಿರುವವರು ಕೆಳಕ್ಕೆ ಹೋಗುತ್ತಾರೆ.',
19: 'ಗುಣಗಳ ಹೊರತು ಬೇರೆ ಕರ್ತನಿಲ್ಲ ಎಂದು ಕಂಡು, ಗುಣಗಳಿಗೆ ಅತೀತವಾದುದನ್ನು ತಿಳಿದಾಗ ದ್ರಷ್ಟ ನನ್ನ ಭಾವವನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
20: 'ದೇಹ ಹುಟ್ಟಲು ಕಾರಣವಾದ ಈ ಮೂರು ಗುಣಗಳನ್ನು ದಾಟಿದ ದೇಹಧಾರಿ ಹುಟ್ಟು, ಸಾವು, ಮುಪ್ಪು ಮತ್ತು ದುಃಖದಿಂದ ಮುಕ್ತನಾಗಿ ಅಮೃತತ್ವವನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
21: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಪ್ರಭು, ಈ ಮೂರು ಗುಣಗಳನ್ನು ದಾಟಿದವನ ಲಕ್ಷಣಗಳೇನು? ಅವನು ಹೇಗೆ ನಡೆದುಕೊಳ್ಳುತ್ತಾನೆ? ಈ ಮೂರು ಗುಣಗಳನ್ನು ಅವನು ಹೇಗೆ ದಾಟುತ್ತಾನೆ?',
22: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಪಾಂಡವ, ಬೆಳಕು, ಚಟುವಟಿಕೆ ಮತ್ತು ಮೋಹ ಬಂದಾಗ ಅವನು ಅವುಗಳನ್ನು ದ್ವೇಷಿಸುವುದಿಲ್ಲ, ಹೋದಾಗ ಅವುಗಳನ್ನು ಬಯಸುವುದಿಲ್ಲ.',
23: 'ಉದಾಸೀನನಂತೆ ಇದ್ದು ಗುಣಗಳಿಂದ ಕಳವಳಗೊಳ್ಳುವುದಿಲ್ಲ; "ಗುಣಗಳೇ ವರ್ತಿಸುತ್ತಿವೆ" ಎಂದು ತಿಳಿದು ಅಲುಗಾಡದೆ ಸ್ಥಿರವಾಗಿರುತ್ತಾನೆ.',
24: 'ಸುಖ-ದುಃಖಗಳಲ್ಲಿ ಸಮನಾದ, ತನ್ನಲ್ಲೇ ನೆಲೆಸಿದ; ಮಣ್ಣು, ಕಲ್ಲು ಮತ್ತು ಚಿನ್ನ ಅವನಿಗೆ ಸಮಾನ; ಪ್ರಿಯ-ಅಪ್ರಿಯ ಸಮಾನ; ಧೀರ; ನಿಂದೆ-ಸ್ತುತಿಗಳನ್ನು ಸಮಾನವಾಗಿ ಕಾಣುವವನು,',
25: 'ಮಾನಾಪಮಾನಗಳಲ್ಲಿ ಸಮನಾದ, ಮಿತ್ರ ಮತ್ತು ಶತ್ರುಪಕ್ಷಗಳಲ್ಲಿ ಸಮನಾದ, ಎಲ್ಲ ಆರಂಭಗಳನ್ನೂ ಬಿಟ್ಟವನು: ಅವನನ್ನು ಗುಣಾತೀತ ಎನ್ನುತ್ತಾರೆ.',
26: 'ಅಚಲ ಭಕ್ತಿಯೋಗದಿಂದ ನನ್ನನ್ನು ಸೇವಿಸುವವನು ಈ ಗುಣಗಳನ್ನು ದಾಟಿ ಬ್ರಹ್ಮಭಾವಕ್ಕೆ ಅರ್ಹನಾಗುತ್ತಾನೆ.',
27: 'ಏಕೆಂದರೆ ಬ್ರಹ್ಮಕ್ಕೆ, ಅವಿನಾಶಿ ಅಮೃತಕ್ಕೆ, ಶಾಶ್ವತ ಧರ್ಮಕ್ಕೆ ಮತ್ತು ಏಕಾಂತ ಸುಖಕ್ಕೆ ಆಧಾರ ನಾನೇ.',
}
